package com.bank.trie;

import java.util.logging.Logger;

// Prefix tree for IFSC branch codes: insert, exact search, prefix check.
public class BranchCodeTrie {

    private static final Logger log = Logger.getLogger(BranchCodeTrie.class.getName());

    private final TrieNode root = new TrieNode();

    public void insert(String code) {
        TrieNode node = root;
        for (char c : code.toCharArray()) {
            node = node.children.computeIfAbsent(c, k -> new TrieNode());
        }
        node.isWord = true;
        log.info("Inserted branch code: " + code);
    }

    public boolean search(String code) {
        TrieNode node = walk(code);
        boolean found = node != null && node.isWord;
        log.info("Exact search '" + code + "' -> " + found);
        return found;
    }

    public boolean startsWith(String prefix) {
        boolean exists = walk(prefix) != null;
        log.info("Prefix '" + prefix + "' -> " + exists);
        return exists;
    }

    private TrieNode walk(String s) {
        TrieNode node = root;
        for (char c : s.toCharArray()) {
            node = node.children.get(c);
            if (node == null) return null; // path fell off the tree
        }
        return node;
    }
}
