package com.bank.trie;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class TrieDemo {

    private static final Logger log = Logger.getLogger(TrieDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Branch Code Type-Ahead (Trie)");
        BranchCodeTrie trie = new BranchCodeTrie();
        trie.insert("NBIN0001234");
        trie.insert("NBIN0005678");
        trie.insert("NBIN0009999");

        trie.search("NBIN0001234"); // true  — exact code
        trie.search("NBIN0001");    // false — prefix, not a full code
        trie.startsWith("NBIN000"); // true  — many codes share this prefix
        trie.startsWith("HDFC");    // false — no code begins with this
    }
}
